#!/usr/bin/env node
/**
 * Fetches the Anthropic API OpenAPI spec to ../specs/.
 *
 * Anthropic's SDKs are generated by Stainless, and each SDK repository used to
 * record the spec it was built from as `openapi_spec_url` in `.stats.yml`.
 * On 2026-09-03 that key was removed from every SDK's `.stats.yml`, so there
 * is no longer a stable public pointer to the current spec. The last
 * published document (2026-09-02) still downloads, so:
 *
 *   1. Look for a NEWER `openapi_spec_url` in `.stats.yml` at HEAD of
 *      github.com/anthropics/anthropic-sdk-typescript (in case Anthropic
 *      restores it) and use it when present.
 *   2. Otherwise fall back to the pinned last-published spec below.
 *
 * The Stainless bucket serves the document as JSON despite its `.yml` name.
 *
 * Usage:
 *   node fetch-specs.ts
 *
 * The spec is saved to:
 *   ../specs/openapi.json
 */

const STATS_URL =
  "https://raw.githubusercontent.com/anthropics/anthropic-sdk-typescript/HEAD/.stats.yml";
const PINNED_SPEC_URL =
  "https://storage.googleapis.com/stainless-sdk-openapi-specs/anthropic/anthropic-465bff21a179090915396565d1ae8f705cf8596e2ec920eb121072f25b8a7d68.yml";
const SPECS_DIR = "../specs";
const OUTPUT_PATH = `${SPECS_DIR}/openapi.json`;
const USER_AGENT = "distilled.cloud-anthropic-spec-mirror";

import { existsSync, mkdirSync } from "fs";
import { writeFile } from "fs/promises";

if (!existsSync(SPECS_DIR)) {
  mkdirSync(SPECS_DIR, { recursive: true });
}

/** `openapi_spec_url` from the TypeScript SDK's `.stats.yml`, if it is back. */
async function discoverSpecUrl(): Promise<string | undefined> {
  try {
    const response = await fetch(STATS_URL, { headers: { "user-agent": USER_AGENT } });
    if (!response.ok) {
      console.warn(`.stats.yml: ${response.status} ${response.statusText} — using pinned spec`);
      return undefined;
    }
    const text = await response.text();
    const match = /^openapi_spec_url:\s*['"]?(\S+?)['"]?\s*$/m.exec(text);
    return match?.[1];
  } catch (err) {
    console.warn(`.stats.yml: ${String(err)} — using pinned spec`);
    return undefined;
  }
}

async function main() {
  const discovered = await discoverSpecUrl();
  const url = discovered ?? PINNED_SPEC_URL;
  console.log(
    discovered
      ? `Found openapi_spec_url in .stats.yml: ${url}`
      : `No openapi_spec_url in .stats.yml — falling back to the last published spec`,
  );
  console.log(`Fetching OpenAPI spec from ${url}...`);

  const response = await fetch(url, {
    headers: { accept: "application/json", "user-agent": USER_AGENT },
  });
  if (!response.ok) {
    throw new Error(`Failed to fetch OpenAPI spec: ${response.status} ${response.statusText}`);
  }

  // Stainless serves JSON under a `.yml` name; parse the text so a content
  // type mismatch cannot trip the fetch API's json() helper.
  const spec = JSON.parse(await response.text()) as Record<string, unknown>;

  // A login page or a gutted response is still valid JSON, but it is not an
  // OpenAPI document — fail here rather than in the generator.
  if (typeof spec.openapi !== "string" || spec.paths === undefined) {
    throw new Error(`${url} returned JSON without \`openapi\`/\`paths\` — not an OpenAPI document`);
  }

  console.log(`Writing spec to ${OUTPUT_PATH}...`);
  // Deterministic: 2-space indent + trailing newline, so a whitespace-only
  // change upstream produces no diff.
  await writeFile(OUTPUT_PATH, JSON.stringify(spec, null, 2) + "\n");

  console.log(`Done! OpenAPI ${spec.openapi} — ${Object.keys(spec.paths as object).length} paths`);
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});
